const memo = rules.map(() => new Map());

function rule(id, pos) {
  const cache = memo[id];
  if (cache.has(pos)) return cache.get(pos);  // has(), not get(): undefined is a result
  const res = ruleImpl[id](pos);              // may backtrack over the input
  cache.set(pos, res);                        // success and failure both cached
  return res;
}
